const sitemaps = [
  "https://www.student.com/sitemaps/sitemap-en-us_0.xml",
  "https://www.student.com/sitemaps/sitemap-en-us_1.xml",
  "https://www.student.com/sitemaps/sitemap-en-us_2.xml",
  "https://www.student.com/sitemaps/sitemap-en-us_3.xml",
  "https://www.student.com/sitemaps/sitemap-en-us_4.xml"
];

for (const sm of sitemaps) {
  const res = await tool.fetch_url({ url: sm });
  const matches = Array.from(res.body.matchAll(/<loc>(.*?)<\/loc>/g))
    .map(m => m[1])
    .filter(url => url.toLowerCase().includes("liverpool"));
  if (matches.length > 0) {
    console.log(`Found in ${sm}:`, matches.slice(0, 10));
    console.log(`Total matches in ${sm}:`, matches.length);
    const lic = matches.filter(u => u.toLowerCase().includes("international") || u.toLowerCase().includes("college"));
    if (lic.length > 0) {
      console.log("Matches with international/college:", lic);
    }
  }
}

