const tabId = 1854033397;
const apiInfo = await browserjs(tabId, async () => {
  const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src);
  const hits = [];
  for (const src of scripts) {
    if (!src.includes('student.com')) continue;
    try {
      const resp = await fetch(src);
      const text = await resp.text();
      if (text.includes("api.") || text.includes("/api/") || text.includes("graphql") || text.includes("backend")) {
        const matches = text.match(/https?:\/\/[a-zA-Z0-9.-]*student\.com[^\s"'`)]*/g) || [];
        hits.push(...matches);
      }
    } catch (e) {}
  }
  return Array.from(new Set(hits));
});
console.log("Found student.com URLs in JS:", apiInfo);

