const tabId = 1854033397;
const gqlInfo = await browserjs(tabId, async () => {
  const scripts = Array.from(document.querySelectorAll('script[src]')).map(s => s.src);
  const operations = [];
  for (const src of scripts) {
    if (!src.includes('student.com')) continue;
    try {
      const resp = await fetch(src);
      const text = await resp.text();
      // Look for query names or graphql operations
      const opMatches = text.match(/(?:query|mutation)\s+([A-Za-z0-9_]+)/g) || [];
      for (const op of opMatches) {
        operations.push({ src, op });
      }
    } catch (e) {}
  }
  return operations;
});
console.log("Operations found:", gqlInfo);

