const query = `
  query SearchPropertiesSRPPropertiesQuery(
    $citySlug: String
    $countrySlug: String
    $universitySlug: String
    $priceMax: Int
    $priceMin: Int
    $bathroomTypes: [String]
    $pageSize: Int
  ) {
    searchProperties(
      citySlug: $citySlug
      countrySlug: $countrySlug
      universitySlug: $universitySlug
      priceMax: $priceMax
      priceMin: $priceMin
      bathroomTypes: $bathroomTypes
      pageSize: $pageSize
    ) {
      properties {
        name
        slug
        cityName
        citySlug
        categories {
          priceMin
          slug
        }
      }
      pagination {
        totalResults
      }
    }
  }
`;

const tests = [
  { universitySlug: "liverpool-international-college" },
  { citySlug: "liverpool" },
  { countrySlug: "uk" }
];

for (const vars of tests) {
  const res = await tool.fetch_url({
    url: "https://gateway.student.com/graphql",
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ query, variables: vars })
  });
  console.log(`Query ${JSON.stringify(vars)}:`);
  console.log(res.body.slice(0, 500));
}

