      universitySlug: $universitySlug
      pageSize: $pageSize
    ) {
      properties {
        name
        slug
        cityName
        citySlug
        categories {
          priceMin
          slug
        }
      }
      pagination {
        totalResults
      }
    }
  }
`;

const tests = [
  { city: "Liverpool" },
  { countryCode: "GB" },
  { countryCode: "UK" },
  { countrySlug: "united-kingdom" }
];

