const types = ["posts", "pages"];
for (const t of types) {
  let page = 1;
  while (true) {
    const url = `https://www.student.com/wp-json/wp/v2/${t}?per_page=100&page=${page}&_fields=id,slug,title,link`;
    const res = await tool.fetch_url({ url });
    if (res.status !== 200) break;
    const items = JSON.parse(res.body);
    if (items.length === 0) break;
    const matches = items.filter(it => {
      const s = (it.title?.rendered + " " + it.slug).toLowerCase();
      return s.includes("liverpool") || s.includes("kaplan") || s.includes("lic");
    });
    if (matches.length > 0) {
      console.log(`Matches in ${t} page ${page}:`, matches);
    }
    page++;
  }
}
console.log("Done searching WP posts and pages");

