const tabId = 1854033397;
const setTests = [
  "/set",
  "/set/",
  "/set/currency",
  "/set/currency/gbp",
  "/set/country",
  "/set/country/gb",
  "/set/country/uk",
  "/set/locale",
  "/set/locale/en-gb"
];

const results = await browserjs(tabId, async (paths) => {
  const out = [];
  for (const p of paths) {
    try {
      const r = await fetch(p);
      out.push({ path: p, status: r.status, url: r.url });
    } catch (e) {
      out.push({ path: p, error: e.message });
    }
  }
  return out;
}, setTests);
console.log(results);

