const posts = [12447, 11665, 11192, 9168, 8980];
for (const id of posts) {
  const res = await tool.fetch_url({ url: `https://www.student.com/wp-json/wp/v2/posts/${id}` });
  const p = JSON.parse(res.body);
  console.log(`=== Post ${id}: ${p.title.rendered} ===`);
  const content = p.content.rendered;
  const sentences = content.split(/[.<>]/).filter(s => 
    s.toLowerCase().includes("bathroom") || 
    s.toLowerCase().includes("en-suite") || 
    s.toLowerCase().includes("ensuite") ||
    s.toLowerCase().includes("price") ||
    s.toLowerCase().includes("£")
  );
  console.log(sentences.map(s => s.trim()).filter(Boolean).join("\n"));
}

